package main

import (
	"fmt"
	"github.com/deckarep/golang-set/v2/mapset"
)

func main() {
	// Create a set
	s := mapset.NewSet[int](1, 2, 3, 4, 5)

	// Test the Elements function
	fmt.Println("Testing Elements function:")
	count := 0
	mapset.Elements(s)(func(elem int) bool {
		fmt.Printf("Element: %d\n", elem)
		count++
		if count == 3 {
			return false // Stop after 3 elements
		}
		return true // Continue
	})

	fmt.Printf("Processed %d elements\n", count)
}
EOF
